import path from 'node:path';
import { fileURLToPath } from 'node:url';
import fs from 'node:fs';

const DATA_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Path to the file, relative to the data directory.' },
        },
        required: ['path'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { path: rel } = args;
  if (typeof rel !== 'string' || rel.length === 0) {
    throw new Error('path is required');
  }
  // Reject absolute paths and traversal
  const resolved = path.resolve(DATA_DIR, rel);
  const relToData = path.relative(DATA_DIR, resolved);
  if (relToData.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error('path must be within the data directory');
  }
  let stat;
  try {
    stat = fs.statSync(resolved);
  } catch (e) {
    throw new Error(`File not found: ${rel}`);
  }
  if (!stat.isFile()) {
    throw new Error(`Not a file: ${rel}`);
  }
  const ext = path.extname(resolved).toLowerCase();
  const text = `${relToData} ${stat.size} bytes ${ext}`;
  return {
    content: [{ type: 'text', text }],
  };
}
